# warehouse/infrastructure/caches.py # Cache never raises. from app.core.logging import logger   class RediswarehouseCache:     """Redis cache for warehouse (never-raise)."""      def __init__(self, redis_client):         self.redis = redis_client      async def get(self, key: str):         try:             return await self.redis.get(f"wh:{key}")         except Exception as e:             logger.warning("wh.cache.get.failed", error=str(e))             return None      async def set(self, key: str, value: str, ttl: int = 300) -> None:         try:             await self.redis.setex(f"wh:{key}", ttl, value)         except Exception as e:             logger.warning("wh.cache.set.failed", error=str(e))      async def delete(self, key: str) -> None:         try:             await self.redis.delete(f"wh:{key}")         except Exception as e:             logger.warning("wh.cache.del.failed", error=str(e))